CustomField.formula:
IF(NOT(ISBLANK(BillingState)),
    IF(CONTAINS($Label.Subregion_AMER_Pacific_Northwest,BillingState + ";"),"Pacific Northwest",
        IF(BillingState = "California" || BillingState = "CA","California",
            IF(CONTAINS($Label.Subregion_AMER_Mountain_West,BillingState + ";"),"Mountain West",
                IF(CONTAINS($Label.Subregion_AMER_Southwest,BillingState + ";"),"Southwest",
                    IF(CONTAINS($Label.Subregion_AMER_Midwest,BillingState + ";"),"Midwest",
                        IF(CONTAINS($Label.Subregion_AMER_Southeast,BillingState + ";"),"Southeast",
                            IF(CONTAINS($Label.Subregion_AMER_Mid_Atlantic,BillingState + ";"),"Mid Atlantic",
                                IF(CONTAINS($Label.Tri_State,BillingState + ";"),"Tri State",
                                    IF(CONTAINS($Label.Subregion_AMER_Northeast,BillingState + ";"),"Northeast","")
                                )
                            )
                        )
                    )
                )
            )
        )
    ),
    ""
)
